using System.Text;
using System.Text.Json;
using Silverfish.Domain.Client;
using Silverfish.Simulation;

namespace Silverfish.Cli;

internal static class CardDataSourceWriter
{
    internal static void Write(Stream destination, CardDataCatalog data)
    {
        using var writer = new StreamWriter(destination, new UTF8Encoding(false), leaveOpen: true) { NewLine = "\n" };
        writer.WriteLine("""
            // <auto-generated>
            // 由 CardDefs.xml 生成。请通过 import-card-data 更新。
            // </auto-generated>
            using Silverfish.Domain;

            namespace Silverfish.Simulation;

            public static partial class CompiledCardData
            {
            """);
        writer.WriteLine(FormattableString.Invariant($"    private const int SourceBuild = {data.SourceBuild};"));
        writer.WriteLine("    private static string CardIds =>");
        // 分段写入字符串常量，编译器会合并成一段。每行数据只存该卡牌 ID 的起始位置。
        var groups = data.Cards.Chunk(64).ToArray();
        for (var i = 0; i < groups.Length; i++)
        {
            var ids = JsonSerializer.Serialize(string.Concat(groups[i].Select(card => card.CardId)));
            writer.WriteLine($"        {ids}{(i == groups.Length - 1 ? ";" : " +")}");
        }

        writer.WriteLine("""

                // ID 偏移、类型、费用、攻击、生命、耐久、关键词、过载、种族掩码低位和高位、派系、替代费用类型。
                private static ReadOnlySpan<int> Rows =>
                [
            """);
        var offset = 0;
        foreach (var metadata in data.Cards)
        {
            var card = SimulationCard.FromMetadata(metadata);
            var definition = card.Definition;
            var keywords = card.Keywords.ToString().Replace(", ", " | CardKeywords.");
            var id = JsonSerializer.Serialize(definition.CardId);
            var races = (ulong)definition.MinionTypes.GetValueOrDefault();
            writer.WriteLine(FormattableString.Invariant(
                $"        {offset}, (int)EntityKind.{definition.Kind}, {definition.PrintedCost}, {definition.PrintedAttack}, {definition.PrintedHealth}, {definition.PrintedDurability}, (int)(CardKeywords.{keywords}), {card.Overload}, {unchecked((int)races)}, {(int)(races >> 32)}, {(int)definition.SpellSchool.GetValueOrDefault()}, {(int)definition.AlternateCost.GetValueOrDefault()}, // {id}"));
            offset += definition.CardId.Length;
        }
        writer.WriteLine("    ];");
        writer.WriteLine("    private static ReadOnlySpan<int> RequirementMasks =>");
        writer.WriteLine("    [");
        foreach (var chunk in data.Cards.Chunk(64))
            writer.WriteLine($"        {string.Join(", ", chunk.Select(PlayReqTags.FromMetadata))},");
        writer.WriteLine("    ];");
        writer.WriteLine("    private static ReadOnlySpan<int> CollectibleMinionRows =>");
        writer.WriteLine("    [");
        var minions = data.Cards.Select((card, row) => (card, row))
            .Where(entry => entry.card.ClientCardType == TAG_CARDTYPE.MINION && entry.card.GetTag(GAME_TAG.COLLECTIBLE) == 1 &&
                entry.card.GetTag(GAME_TAG.TITAN) == 0 && entry.card.GetTag(GAME_TAG.HEALTH) > 0 &&
                entry.card.ClientCardSet is not (TAG_CARD_SET.CORE_HIDDEN or TAG_CARD_SET.VANILLA))
            .Select(entry => entry.row);
        foreach (var chunk in minions.Chunk(64))
            writer.WriteLine($"        {string.Join(", ", chunk)},");
        writer.WriteLine("    ];");
        writer.WriteLine("    private static ReadOnlySpan<int> CardClassMasks =>");
        writer.WriteLine("    [");
        foreach (var chunk in data.Cards.Chunk(64))
            writer.WriteLine($"        {string.Join(", ", chunk.Select(card => unchecked((int)card.ToDefinition().ClassMask)))},");
        writer.WriteLine("""
                ];
            }
            """);
    }
}
